using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using Sandbox.Layout;

namespace LayoutTests;

/// <summary>
/// Deeply nested auto-sized trees (20 levels of alternating row / column flex containers with text-like
/// measure functions, auto margins, percentages, min/max, wrapping, scroll containers, RTL and fractional
/// placement). Incremental layout must match a freshly built tree within 0.001 after a deep content change
/// and a root resize. Scenarios without intentional cache corrections also retain historical snapshots.
///
/// To regenerate after an intentional algorithm change, run <see cref="DeepTreeFixtures.Dump"/> for every
/// scenario in <see cref="DeepTreeFixtures.Scenarios"/> and paste the output over the constants below.
/// </summary>
[TestClass]
public class DeepTreeTests
{
	[TestMethod] public void Text() => Check( "text", Expected_text );
	[TestMethod] public void Percent() => Check( "percent", Expected_percent );
	[TestMethod] public void MinMax() => Check( "minmax", Expected_minmax );
	[TestMethod] public void AutoMargins() => Check( "automargins", Expected_automargins );
	[TestMethod] public void WrapGap() => Check( "wrapgap", Expected_wrapgap );
	[TestMethod] public void Scroll() => Check( "scroll", Expected_scroll );
	[TestMethod] public void Everything() => Check( "everything", Expected_everything );
	[TestMethod] public void EverythingUnconstrained() => Check( "everything_unconstrained", Expected_everything_unconstrained );
	[TestMethod] public void EverythingRtl() => Check( "everything_rtl", Expected_everything_rtl );
	[TestMethod] public void EverythingFractionalPlacement() => Check( "everything_pixelgrid", Expected_everything_pixelgrid );
	[TestMethod] public void GrowChain() => Check( "growchain", Expected_growchain );

	// Constraints within 0.0001 are treated as equal. Anything beyond this tolerance is a real difference.
	private const float Tolerance = 0.001f;
	private static readonly HashSet<string> CorrectedCacheScenarios = new()
	{
		"percent", "everything_unconstrained", "everything_rtl", "everything_pixelgrid",
	};

	private static void Check( string scenario, string expected )
	{
		var actual = DeepTreeFixtures.Dump( scenario );
		CompareDumps( scenario + " fresh", DeepTreeFixtures.DumpFresh( scenario ), actual );
		if ( CorrectedCacheScenarios.Contains( scenario ) ) return;
		CompareDumps( scenario, expected, actual );
	}

	private static void CompareDumps( string scenario, string expected, string actual, float tolerance = Tolerance )
	{
		if ( actual == expected ) return;

		var expectedPasses = expected.Split( '\n' );
		var actualPasses = actual.Split( '\n' );
		Assert.AreEqual( expectedPasses.Length, actualPasses.Length, $"{scenario}: pass count" );

		for ( int p = 0; p < expectedPasses.Length; p++ )
		{
			var e = expectedPasses[p].Split( ';' );
			var a = actualPasses[p].Split( ';' );
			Assert.AreEqual( e.Length, a.Length, $"{scenario}: pass {p} node count" );

			for ( int i = 0; i < e.Length; i++ )
			{
				if ( e[i] == a[i] ) continue;

				var ev = e[i].Split( ',' );
				var av = a[i].Split( ',' );
				for ( int k = 0; k < 4; k++ )
				{
					var expectedValue = float.Parse( ev[k], CultureInfo.InvariantCulture );
					var actualValue = float.Parse( av[k], CultureInfo.InvariantCulture );
					if ( float.IsNaN( expectedValue ) && float.IsNaN( actualValue ) ) continue;
					if ( float.IsNaN( expectedValue ) || float.IsNaN( actualValue ) || MathF.Abs( expectedValue - actualValue ) > tolerance )
					{
						Assert.Fail( $"{scenario}: pass {p}, node {i}: expected [{e[i]}] got [{a[i]}]" );
					}
				}
			}
		}
	}

